\label{lem1}
Let $G$ be a graph with a cut edge $e=\{v_1,v_2\}$. Let $G_1$ and $G_2$ be the  connected components of $G-e$ containing $v_1$ and $v_2$, respectively, with 
$|V(G_i)|\geq 2$ for $i=1,2$. Let $G'$ be the graph obtain from $G$ by identifying $v_1$ and $v_2$ and adding a pendant  vertex $v_2$  at the identified vertex  $v_{1}$(see Figure \ref{fig1}). Then $\epsilon_G(x)<\epsilon_{G'}(x)$ for all $x\in V(G)- v_2$.

Let $G_1$ and $G'_2$ be the subgraphs  of $G'$ such that $G_1\cup G'_2=G'$ and $V(G_1)\cap V(G'_2)=\{v_1\}$. 

For $x\in V(G_1)$, let $\epsilon_{G'}(x)=f_{G'}(x,r)$. Clearly $r\neq v_1$.\\ 
Suppose $r\in V(G'_2)$. Then $f_{G'}(x,r)=f_{G_1}(x,v_1)f_{G'_2}(v_1,r)$.  We have two cases here.\\
{\bf Case-I:} $r\neq v_2$\\
Since $ 2f_{G_2}(v_2,r)= f_{G'_2}(v_1,r)$, we have
\begin{align*}
   &\epsilon_{G}(x)\leq f_G(x,r)=f_{G_1}(x,v_1)f_{G_2}(v_2,r)< f_{G_1}(x,v_1)f_{G'_2}(v_1,r)= f_{G'}(x,r)=\epsilon_{G'}(x). 
\end{align*} 
\noindent {\bf Case-II:} $r= v_2$\\
 In this case, we have 
\begin{align*}
   &\epsilon_{G}(x)< f_G(x,v_2)=f_{G_1}(x,v_1)f_{G_2}(v_2)= f_{G_1}(x,v_1)f_{G'_2}(v_1,v_2)= f_{G'}(x,v_2)=\epsilon_{G'}(x). 
\end{align*}
Suppose $r\in V(G_1)$. Then $f_{G'}(x,r)=f_{G_1}(x,r)+f_{G_1}(x,r,v_1)(f_{G'_2}(v_1) -1)$ and $f_{G}(x,r)=f_{G_1}(x,r)+f_{G_1}(x,r,v_1)f_{G_2}(v_2)$. Since $f_{G'_2}(v_1)=2f_{G_2}(v_2)$, we have
\begin{align*}
 f_{G'}(x,r)-f_{G}(x,r)=f_{G_1}(x,r,v_1)(f_{G'_2}(v_1)-1-f_{G_2}(v_2))>0 \;\;(\mbox{as $|V(G_2)|>1$}) .
\end{align*}
So, $\epsilon_{G}(x)\leq f_{G}(x,r)<f_{G'}(x,r)=\epsilon_{G'}(x)$. Hence $\epsilon_{G}(x)<\epsilon_{G'}(x)$ for $x\in V(G_1)$.\\

Now let $x\in V(G'_2)\setminus \{v_1,v_2\}$ and suppose $\epsilon_{G'}(x)=f_{G'}(x,r)$. Clearly $r\neq v_1$.\\
Suppose $r\in V(G_1)$. Then $f_{G'}(x,r)=f_{G'_2}(x,v_1)f_{G_1}(v_1,r)$. Since $f_{G'_2}(x,v_1)=2f_{G_2}(x,v_2)$, 
 \begin{align*}
  \epsilon_{G}(x)\leq f_G(x,r)=f_{G_2}(x,v_2)f_{G_1}(v_1,r)< f_{G'_2}(x,v_1)f_{G_1}(v_1,r)=f_{G'}(x,r)=\epsilon_{G'}(x).
 \end{align*}
Suppose $r\in V(G'_2)$. Then $f_{G'}(x,r)=f_{G'_2}(x,r,\bar{v_1})+f_{G'_2}(x,r,{v_1})+f_{G'_2}(x,r,v_1)(f_{G_1}(v_1)-1)$ and
    $f_G(x,r)=f_{G_2}(x,r,\bar{v_2})+f_{G_2}(x,r,v_2)+f_{G_2}(x,r,v_2)f_{G_1}(v_1)$.
Since $f_{G'_2}(x,r,\bar{v_1})=f_{G_2}(x,r,\bar{v_2})$ and $f_{G'_2}(x,r,{v_1})=2f_{G_2}(x,r,v_2)$, we have
\begin{align*}
   f_{G'}(x,r)-f_G(x,r)&=f_{G'_2}(x,r,v_1)f_{G_1}(v_1)-f_{G_2}(x,r,v_2)-f_{G_2}(x,r,v_2)f_{G_1}(v_1)\\
                       &=2f_{G_2}(x,r,v_2)f_{G_1}(v_1)-f_{G_2}(x,r,v_2)-f_{G_2}(x,r,v_2)f_{G_1}(v_1)\\
                       &=f_{G_2}(x,r,v_2)(f_{G_1}(v_1)-1)\\
                       &>0 \;\;(\mbox{as $|V(G_1)|>1$}) .
\end{align*}
So, $\epsilon_{G}(x)\leq f_G(x,r)< f_{G'}(x,r)=\epsilon_{G'}(x)$. Hence $\epsilon_{G}(x)<\epsilon_{G'}(x)$ for $x\in V(G'_2)\setminus \{v_1,v_2\}$ and this proves the result.

Let $X_1$ be the component of $T-v_1v_2$ containing $v_1$, $X_2$ be the component of  $T-v_1v_2-v_2v_3$ containing $v_2$, $\ldots$ , $X_d$ be the component of  $T-v_{d-1}v_d-v_dr$ containing $v_d$ (see Figure \ref{fig3}). Then
\begin{align*}
    f_T(v_1,r)=\prod_{i=1}^{d} f_{X_i}(v_i),\;\; f_T(v_1,v_d,\overline{r})=\prod_{i=1}^{d} f_{X_i}(v_i)
\end{align*} 
and for $1\leq j \leq d-1$
\begin{align*}
   f_T(v_1,v_j,\overline{v_{j+1}})= \prod_{i=1}^{j} f_{X_i}(v_i).
\end{align*}
So,
\begin{align*}
 f_T(v_1)&=f_{X_1}(v_1)+f_{X_1}(v_1)f_{X_2}(v_2)+\cdots+2f_{X_1}(v_1)f_{X_2}(v_2)\cdots f_{X_d}(v_d)\\
         &=f_{X_1}(v_1)+f_{X_1}(v_1)f_{X_2}(v_2)+\cdots+2f_T(v_1,r).
\end{align*} 
  Thus, $f_T(v_1)-2f_T(v_1,r)\geq 0$ and equality happens if and only if $f_{X_1}(v_1)+f_{X_1}(v_1)f_{X_2}(v_2)+\cdots+f_{X_1}(v_1)f_{X_2}(v_2)\cdots f_{X_{d-1}}(v_{d-1})=0$ and hence equality happens if and only if $d=1.$

\label{lem3}
Let $G$ and $G'$ be the graphs mentioned in Lemma \ref{lem1} (Figure \ref{fig1}). Suppose  $\epsilon_{G'}(v_2)=f_{G'}(v_2,r)$. Then the following hold:
\begin{enumerate}
    \item[(i)] $\epsilon_{G'}(v_1)=min\{f_{G'}(v_1,v_2),f_{G'}(v_1,r)\}$;
    \item[(ii)] If $G_1$ is a tree then $\epsilon_{G'}(v_1)=f_{G'}(v_1,r)$. 
\end{enumerate}

\begin{enumerate}
\item[(i)] Let $G_1$ and $G'_2$ be the subgraphs  of $G'$ such that $G_1\cup G'_2=G'$ and $V(G_1)\cap V(G'_2)=\{v_1\}$. Clearly $r\neq v_2$. Suppose $r\in V(G'_2)\setminus v_2$. 

If $y\in V(G_1)$ then $\epsilon_{G'}(v_2)=f_{G'}(v_2,r)$ implies $f_{G'_2}(v_2,r)f_{G_1}(v_1)\leq f_{G'_2}(v_2,v_1)f_{G_1}(v_1,y)$. Since $\frac{f_{G'_2}(v_1,r)}{2}=f_{G'_2}(v_2,r)$ and $\frac{f_{G'_2}(v_1)}{2}=f_{G'_2}(v_2,v_1)$,  $\frac{f_{G'_2}(v_1,r)}{2}f_{G_1}(v_1)\leq \frac{f_{G'_2}(v_1)}{2}f_{G_1}(v_1,y)$. So,
\begin{align}\label{a1}
  f_{G'}(v_1,r) =f_{G'_2}(v_1,r)f_{G_1}(v_1)\leq f_{G'_2}(v_1)f_{G_1}(v_1,y)=f_{G'}(v_1,y).
\end{align}
If $y\in V(G'_2)\setminus v_2$ then $f_{G'_2}(v_2, r)\leq f_{G'_2}(v_2,y)$. Since $\frac{f_{G'_2}(v_1,r)}{2}=f_{G'_2}(v_2,r)$ and $\frac{f_{G'_2}(v_1,y)}{2}=f_{G'_2}(v_2,y)$, we have  $\frac{f_{G'_2}(v_1,r)}{2}f_{G_1}(v_1)\leq \frac{f_{G'_2}(v_1,y)}{2}f_{G_1}(v_1)$. Thus
\begin{align}\label{a2}
   f_{G'}(v_1,r)=f_{G'_2}(v_1,r)f_{G_1}(v_1)\leq f_{G'_2}(v_1,y)f_{G_1}(v_1)=f_{G'}(v_1,y). 
\end{align}
By $(\ref{a1})$ and $(\ref{a2})$ we get $\epsilon_{G'}(v_1)=min\{f_{G'}(v_1,v_2),f_{G'}(v_1,r)\}$ if $r\in V(G'_2)\setminus v_2$. Similarly, we can prove that $\epsilon_{G'}(v_1)=min\{f_{G'}(v_1,v_2),f_{G'}(v_1,r)\}$ if $r\in V(G_1)$. This proves the result.

\item [(ii)]  Let $x$  be a pendant vertex of $G_1$. Then $f_{G'}(v_1,x)=f_{G_1}(v_1,x)f_{G'_2}(v_1)$ and $f_{G'}(v_1,v_2)=f_{G_1}(v_1)f_{G'_2}(v_1,v_2)$. Since $f_{G'_2}(v_1)=2f_{G_2}(v_2)$ and $f_{G'_2}(v_1,v_2)=f_{G_2}(v_2)$, we have
\begin{align*}
  f_{G'}(v_1,v_2)-f_{G'}(v_1,x)&=f_{G_1}(v_1)f_{G_2}(v_2)-2f_{G_1}(v_1,x)f_{G_2}(v_2)\\&=(f_{G_1}(v_1)-2f_{G_1}(v_1,x))f_{G_2}(v_2)\\& \geq 0 \;\; (\mbox{by Lemma $\ref{lem2}).$}
\end{align*}
Thus $f_{G'}(v_1,r)\leq f_{G'}(v_1,x)\leq f_{G'}(v_1,v_2)$ where the first inequality follows from $(\ref{a1})$ and hence from part $(i)$ the result follows.
\end{enumerate}

\label{lem6}
Let $U^p_{n,g}\in \mathcal{U}_{n,g}$ with all $n-g$ pendant vertices attached to $v_1$ of $C_g:v_1v_2\cdots v_gv_1$. Suppose $v \in V(U^p_{n,g})$. Then the following hold:
\begin{enumerate}
\renewcommand{(\roman{enumi})}{(\roman{enumi})}
\item If $n-g\geq 2$, then  $\epsilon_{U^p_{n,g}}(v)=f_{U^p_{n,g}}(v,y)$, where $y$ is a pendant vertex.
\item If $n-g=1$ and $z$ is the pendant vertex of $U^p_{n,g}$ then 
  $$\epsilon_{U^p_{n,g}}(v)=\left\{
\begin{array}{ll}
f_{U^p_{n,g}}(v,v_{\lfloor \frac{g+2}{2} \rfloor}), &\text{if $v=z$;}\\
f_{U^p_{n,g}}(v,z),  &\text{otherwise.}\\
\end{array}
\right.$$
\end{enumerate}

\begin{enumerate}
\item[(i)] Let $x,y$ be two pendant vertices of $U^p_{n,g}$ and let $v_j\neq v_1$ be a vertex on $C_g$. Then  $f_{U^p_{n,g}}(x,y)=2^{n-g-2}f_{C_g}(v_1)$. By Lemma \ref{lem4}, we have  $f_{U^p_{n,g}}(x,y)=2^{n-g-2}\left(2g+\binom{g-1}{2}\right)=2^{n-g-2}\left(\frac{g^2+g+2}{2}\right)$. Also, 
\begin{align*}
 f_{U^p_{n,g}}(x,v_j)=2^{n-g-1}f_{C_g}(v_1,v_j)&=2^{n-g-1}\left(2g-1+\binom{g-j}{2}+\binom{j-2}{2}\right)\\
                                                &=2^{n-g-2}(g^2-2gj+2j^2+3g-4j+4). 
\end{align*}
So,
\begin{align*}
  f_{U^p_{n,g}}(x,v_j)-f_{U^p_{n,g}}(x,y)&= 2^{n-g-3}(g^2-4gj+4j^2+5g+6-8j)\\
                                         &=2^{n-g-3}((g-2j+2)^2+g+2)>0,  
\end{align*}

 and also $f_{U^p_{n,g}}(x,v_j)\leq f_{U^p_{n,g}}(x,v_1)$, we have $\epsilon_{U^p_{n,g}}(x)=f_{U^p_{n,g}}(x,y)$.\\


Now consider the vertex $v_1$. We have $f_{U^p_{n,g}}(v_1,y)=2f_{U^p_{n,g}}(x,y)<2f_{U^p_{n,g}}(y,v_j)=f_{U^p_{n,g}}(v_1,v_j)$. Therefore $f_{U^p_{n,g}}(v_1,y)<f_{U^p_{n,g}}(v_1,v_j)$ for  $2\leq j\leq g$. Thus $\epsilon_{U^p_{n,g}}(v_1)=f_{U^p_{n,g}}(v_1,y)$.\\


Let $v_k$ and $v_l$ be two distinct vertices  of $C_g$ with $2\leq k,l\leq g$. Then 
\begin{align}\label{a3}
f_{U^p_{n,g}}(v_k,y)=2^{n-g-1}f_{C_g}(v_k,v_1)=2^{n-g-2}(g^2-2gk+2k^2+3g-4k+4). 
\end{align}

We have $f_{U^p_{n,g}}(v_k,v_l)=f_{C_g}(v_k,v_l,\overline{v_1})+2^{n-g}f_{C_g}(v_k,v_l,v_1).$ First assume $k<l$. Then $f_{C_g}(v_k,v_l,\overline{v_1})=(k-1)(g-l+1)$
and 
\begin{align*}
f_{C_g}(v_k,v_l,v_1)&=f_{C_g}(v_k,\ldots,v_1,v_g,v_{g-1},\ldots,v_l)+f_{C_g}(v_k,\ldots,v_l)- f_{C_g}(v_k,v_l,\overline{v_1})-1\\
                    &=2(l-k)+\binom{l-k-1}{2}+2(g-l+k)+\binom{g-l+k-1}{2}-(k-1)(g-l+1)-1\\
                    &=3g-l-k-gk+kl+\binom{l-k-1}{2}+\binom{g-l+k-1}{2}\\
                    &=3g-l-k-gk+kl+\frac{g^2+2l^2+2k^2-4kl+2gk-2gl-3g+4}{2}.                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
\end{align*}
Thus, 
\begin{align}\label{a4}
f_{U^p_{n,g}}(v_k,v_l)=(k-1)(g-l+1)+2^{n-g-1}(g^2+2l^2+2k^2+3g+4-2kl-2gl-2l-2k).
\end{align}
 So by (\ref{a3}) and (\ref{a4}), we get $f_{U^p_{n,g}}(v_k,v_l)- f_{U^p_{n,g}}(v_k,y)=(k-1)(g-l+1)+2^{n-g-2}((g-2l+k+1)^2+(k-1^2)+g+2)>0.$\\   

Similarly, it can be checked that for $k>l$, $f_{U^p_{n,g}}(v_k,v_l)- f_{U^p_{n,g}}(v_k,y)>0$. Since $f_{U^p_{n,g}}(v_k,v_1)> f_{U^p_{n,g}}(v_k,y)$, we have 
 $\epsilon_{U^p_{n,g}}(v_k)=f_{U^p_{n,g}}(v_k,y)$ for $2\leq k\leq g$. This proves the result.

\item[(ii)]  Let $z$  be the the unique pendant vertex adjacent to $v_1$. Using a similar argument as in the first part, we can prove that for $1\leq i\leq g$,  $\epsilon_{U^p_{n,g}}(v_i)=f_{U^p_{n,g}}(v_i,z)$. Since $f_{U^p_{n,g}}(z,v_j)=f_{C_g}(v_1,v_j)$ and by Proposition $\ref{prop1}$ we know that $f_{C_g}(v_1,v_j)\geq f_{C_g}(v_1,v_{\lfloor \frac{g+2}{2}\rfloor})$ and this proves the result.
\end{enumerate}

\label{lem8}
Let $n\geq 4$. Then  $ES(U^p_{n,3})=
      \begin{cases}
           22 , & if\  n=4;\\
           2^{n-5}(13+7n) , & if \ n\geq 5.
         \end{cases}$

\label{zha1}
Let $T$ be a tree. Then the following hold:
\begin{enumerate}
\item[(i)] For $v\in V(T),$ if $\epsilon(v)= f_T(v,u)$ then $u$ is a pendant vertex;
\item[(ii)] If $\epsilon^d(T)=f_T(u,v)$ then both $u$ and $v$ are pendant vertices;
\item[(iii)] If $\epsilon^d(T)=f_T(u,v)$ for some pendant vertices $u$ and $v$ then $\epsilon(w)=\min\{f_T(w,u), f_T(w,v)\}$ for any $w\in V(T)$.
\end{enumerate}

\label{lem11}
Suppose $d=2k$. Then
  \begin{enumerate}
  \renewcommand{(\roman{enumi})}{(\roman{enumi})}
\item $\epsilon_{T^e_{n,d}}(v_i)=
      \begin{cases}
           f_{T^e_{n,d}}(v_i,v_d),& \;\mbox{if}\;\;  0\leq i\leq k;\\
           f_{T^e_{n,d}}(v_i,v_0),& \;\mbox{if}\;\; k\leq i\leq d.
         \end{cases}$  
\item $\epsilon_{T^e_{n,d}}(x)=f_{T^e_{n,d}}(x,v_0)=f_{T^e_{n,d}}(x,v_d)$, where $x$ is a pendant vertex attached to $v_k$.
  \end{enumerate}

\begin{enumerate}
\item[(i)] For $0\leq i\leq k$, we have $f_{T^e_{n,d}}(v_i,v_0)=(k-i)+(k+1) 2^{n-d-1}$  and $f_{T^e_{n,d}}(v_i,v_d)=(i+1)2^{n-d-1}$. Then $f_{T^e_{n,d}}(v_i,v_0)-f_{T^e_{n,d}}(v_i,v_d)=(k-i)(1+2^{n-d-1})\geq 0$  and equality holds if $i=k$. So, by Lemma $\ref{lem10}$, $\epsilon_{T^e_{n,d}}(v_i)=f_{T^e_{n,d}}(v_i,v_d)$. Similarly, we can show that for $k\leq i\leq d$, $\epsilon_{T^e_{n,d}}(v_i)=f_{T^e_{n,d}}(v_i,v_0)$.
\item[(ii)] We have $f_{T^e_{n,d}}(x,v_0)=2^{n-d-2}(k+1)=f_{T^e_{n,d}}(x,v_d).$ So, by Lemma $\ref{lem10}$, $\epsilon_{T^e_{n,d}}(x)=f_{T^e_{n,d}}(x,v_0)=f_{T^e_{n,d}}(x,v_d)$.
\end{enumerate}

\label{rem3}
Let $3\leq d\leq n-2$. Then the eccentric subgraph index of  $T^e_{n,d}$ is 
 \begin{align*}
   ES(T^e_{n,d})&=2\displaystyle\sum_{i=0}^{k-1} (i+1)2^{n-d-1}+(k+1)2^{n-d-1}+(n-d-1)(k+1)2^{n-d-2}\\
   &=k(k+1)2^{n-d-1}+(k+1)2^{n-d-1}+(n-d-1)(k+1)2^{n-d-2}\\
   &=(k+1)^22^{n-d-1}+(n-d-1)(k+1)2^{n-d-2}\\
   &=(n+1)(\frac{d+2}{2})2^{n-d-2}.
 \end{align*}

\label{lem12}
Let $d=2k-1$ and let $T=T^{o(r,s)}_{n,d}$. Then
\begin{enumerate}
  \renewcommand{(\roman{enumi})}{(\roman{enumi})}
\item $\epsilon_T(v_i)=
      \begin{cases}
           f_T(v_i,v_d),& \;\mbox{if}\;\;  0\leq i\leq k-1;\\
           f_T(v_i,v_0),& \;\mbox{if}\;\; k\leq i\leq d.
         \end{cases}$  
\item $\epsilon_T(x)=
      \begin{cases}
           f_T(x,v_d),& \;\mbox{if $x$ is a pendant vertex attached to $v_{k-1}$;}\\
           f_T(x,v_0),& \;\mbox{if $x$ is a pendant vertex attached to $v_{k}$.}
         \end{cases}$
\end{enumerate}

\begin{enumerate}
\item [(i)] For $0\leq i\leq k-1$, we have $f_T(v_i,v_0)=(k-1-i)+2^r+k2^{r+s}$ and $f_T(v_i,v_d)=(i+1)2^{r+s}$. Then, $f_T(v_i,v_0)-f_T(v_i,v_d)=2^r+(k-i-1)(1+2^{r+s})>0$. So, by Lemma $\ref{lem10}$, $\epsilon_T(v_i)=f_T(v_i,v_d)$. Similarly, it can be checked that for $k\leq i\leq d$, $\epsilon_T(v_i)=f_T(v_i,v_0)$.

\item[(ii)] Let $x$ be a pendant vertex attached to $v_{k-1}$. So, $ f_T(x,v_0)=2^{r-1}+k2^{r+s-1}$ and $f_T(x,v_d)=k2^{r+s-1}$. Then  $f_T(x,v_0)-f_T(x,v_d)=2^{r-1}>0$. So, by Lemma $\ref{lem10}$, $\epsilon_T(x)=f_T(x,v_d)$. Similarly, it can be checked that $\epsilon_T(x)=f_T(x,v_0)$ if $x$ be a pendant vertex attached to $v_k$. 
\end{enumerate}

\label{rem4}
Let $3\leq d\leq n-2$. Then the eccentric subgraph index of  $T^{o(r,s)}_{n,d}$ is 
 \begin{align*}
   ES(T^{o(r,s)}_{n,d})&=\displaystyle\sum_{i=0}^{k-1} (i+1)2^{r+s}  +\displaystyle\sum_{i=k}^{2k-1}2^{r+s}(2k-i)+k(r+s)2^{r+s-1}\\
   &=k(k+1)2^{r+s}+k(r+s)2^{r+s-1}\\
   &=k(k+1)2^{n-d-1}+k(n-d-1)2^{n-d-2}\;\; \mbox{($r+s=n-d-1)$}\\
   &=(\frac{d+1}{2})(n+2)2^{n-d-2}.
 \end{align*}
Since $ES(T^{o(r,s)}_{n,d})$  dose not depend on $r$ or $s$, hence $ES(T^{o(r,s)}_{n,d})$ is fixed for any $r,s\geq 0$ with $r+s=n-d-1.$

\label{thm5}
Let $3\leq d\leq n-2$ and let $T\in \mathcal{T}^n_{d}$. 
  \begin{enumerate}
  \renewcommand{(\roman{enumi})}{(\roman{enumi})}
      \item Suppose $d$ is even. Then $ES(T)\leq (n+1)(\frac{d+2}{2})2^{n-d-2}$  with equality happens if and only if $T\cong T^e_{n,d}$.
      \item Suppose $d$ is odd. Then $ES(T)\leq (\frac{d+1}{2})(n+2)2^{n-d-2}$ with equality happens if and only if $T\cong T^{o(r,s)}_{n,d}$ for some $r,s\geq 0$ with $r+s=n-d-1$.
  \end{enumerate}

\label{lem14}
Let $2\leq k\leq n-3$ and let $K^k_{n-k}$ be the graph defined as above. 
\begin{enumerate}
\renewcommand{(\roman{enumi})}{(\roman{enumi})}
\item Then $\epsilon(v_1)=min\{f_{K^k_{n-k}}(v_1,v_j), f_{K^k_{n-k}}(v_1,x)\}$ where $j\neq 1$ and for $2\leq i\leq n-k$, $\epsilon(v_i)=f_{K^k_{n-k}}(v_i,x)$ where $x$ is a pendant vertex.     
\item Let $x$ and $y$ be  pendant vertices at $v_1$. Then $\epsilon(x)=\min\{f_{K^k_{n-k}}(x,y),f_{K^k_{n-k}}(x,v_j)\}$ where $j\neq 1$.
\end{enumerate}
\begin{proof}
\begin{enumerate}
\item [(i)] 
Let $2\leq r,s\leq n-k$. We have $f_{K^k_{n-k}}(v_1,v_r)=2^kf_{K_{n-k}}(v_1,v_r)=2^k f_{K_{n-k}}(v_1,v_s)$. Let $x,y$ be pendant vertices of $K^k_{n-k}$. Then $f_{K^k_{n-k}}(v_1,x) =f_{K^k_{n-k}}(v_1,y)=2^{k-1}f_{K_{k-n}}(v_1)$. So, $\epsilon_{K^k_{n-k}}(v_1)=min\{f_{K^k_{n-k}}(v_1,v_j),f_{K^k_{n-k}}(v_1,x)\}$ where $j\neq 1$.\\

